Let \{a,b,c\} be a subset of $X$. We define $T_1$, $T_2$, and $T_3$ to be three distinct caterpillar trees of size $n \geq 4$ that differ only in the placement of three taxa $a$, $b$, and $c$, such that for each tree $v_{int}(a), v_{int}(b)$ and $v_{int}(c)$ are incident to $e_1$. Denote $\mathcal{S}$ the set of $n-3$ sets $\displaystyle\bigcup_{i=1}^{n-3}Y_i=\{a,b,c,y|y \in X-\{a,b,c\}\}$ and let $\mathcal{S'}$ be the complement of $\mathcal{S}$. We observe that for all $Y\in \mathcal{S'}$ we have $T_1|Y=T_2|Y=T_3|Y$, but $T_1 \neq T_2 \neq T_3$.  Therefore, $S'$ is not decisive.  Since $|\mathcal{S'}|={n \choose 4} - (n-3)$ the minimal number $k(n)$ such that every collection $\mathcal{S}$ of quartets with $|\mathcal{S}| \geq k$ is decisive is greater than ${n \choose 4} - (n-3)$.
\end{proof}

\begin{proof}
Let $T$ be a binary phylogenetic tree on a taxon set $X$ and let $e_1$ be an interior edge adjacent to a cherry. The tree is connected, which implies we can label the remaining interior edges $\{e_2, \cdots, e_{n-3} \}$ such that $e_j$ is adjacent to some $e_i$ with $i <j$.

Let $e_j$ be adjacent to $e_i$ with $i<j$. We know that $e_i$ separates $T$ into two connected components $T_i^a$ and $T_i^b$. Moreover, $e_j$ separates $T$ into two connected components $T_j^a$ and $T_j^b$. Because $e_i$ and $e_j$ are adjacent, $supp(T_i^b) \cap supp(T_j^a) \neq \emptyset$. Let $q_i=ab|cd$ and $q_j=ac|de$ such that $a \in supp(T_i^a)$, $c \in supp(T_j^b)$, and $d \in supp(T_i^b) \cap supp(T_j^a)$. Thus, $q_i$ and $q_j$ are linked for all $e_i$ and $e_j$ in $T$. Thus, we have a linked system that makes up the first row of our matrix. 

Using quartet tree substitution, construct vines $v(q_i)$ and $v(q_j)$. By Theorem \ref{linkedquartets}  the vines  $v(q_j)$ and $v(q_i)$ are linked. Thus, we have $n-3$ disjoint columns of quartet trees in our matrix. Additionally, for each pair of linked quartet trees $\{q_i,q_j\}$ in row one, there exists a pair $\{q_i(x),q_j(x)\}$ in the remaining rows of the matrix that are linked. Thus, we have $n-3$ rows of linked systems.  

Therefore, $Q_T$ contains a meshed system. 
\end{proof}

\begin{proof}
Let $\mathcal{S}$ be a collection of quartets on a taxon set $X=[n]$, with $|\mathcal{S}| \ge {n \choose 4} - (n-4)$. Let $T$ and $T'$ be two phylogenetic trees such that $T|Y=T$'$|Y$ for all $Y \in \mathcal{S}$. We define $Q \subset Q_T$ to be the collection of $T|Y$ for all $Y \in \mathcal{S}$. By Theorem \ref{number}, $Q_T$ contains a meshed system $M$. By the pigeon hole principle, if  $|Q| \geq {n \choose 4} - (n-4)$ then $Q$ must contain one of the linked systems in $M$, and by Theorem \ref{hierarchy}, $Q$ is definitive.  Thus, $T$ is the unique tree which displays $Q$.  However since $Q$ is also $T'|Y$ for all $Y \in \mathcal{S}$, we must have $T=T'$.  Therefore, $\mathcal{S}$ is decisive. Moreover, Theorem \ref{ge} shows that $k \geq {n \choose 4} - (n-4)$.  Therefore  $k(n)={n \choose 4} - (n-4)$ is the minimal number such that every collection of quartets with $|\mathcal{S}| \geq k$ is decisive.
\end{proof}

\begin{proof}
 Let $\mathcal{S}$ be a collection of $k$ quartets.  Let $T$ and $T'$ be two phylogenetic trees such that $T|Y=T'|Y$ for all $Y \in \mathcal{S}$. We define $Q \subset Q_T$ to be the collection of $T|Y$ for all $Y \in \mathcal{S}$.  Following Theorem \protect\ref{thm:big}, if $Q$ contains a definitive set of quartet trees, then $S$ is decisive.  By Theorem \protect\ref{hierarchy}, if a collection of compatible quartet trees contains a linked system of quartets, then it is definitive. Thus, the probability that a collection $\mathcal{S}$ is decisive is at least the probability that $Q$ contains one of the $n-3$ disjoint linked systems constructed in Theorem \protect\ref{number}. The formula follows from applying the inclusion-exclusion principle to count the number of subsets of size $k$, which contain one of the disjoint systems of linked quartets. 
\end{proof}

\begin{prop} 
(Example 3.7 of \cite{bocker1998})
If $T$ is a binary tree such that the interior edges of $T$ are labeled $E=\{e_1,...,e_{n-3}\}$, and $Q$ is a system of quartet trees such that each $q_i \in Q$ distinguishes a unique edge $e_i$ in $T$ with \[|supp(q_i)\backslash \bigcup_{j<i} supp(q_j)|= 1\] for $i=2,...,n-3$, then $Q$ is definitive. 
\label{bocker2}
\end{prop}

\label{thm:big}
The  number $k(n)={n \choose 4} - (n-4)$ is the smallest number such that every collection of quartets $\mathcal{S}$ on a taxon set $X=[n]$ such that  $\mathcal{S} \geq k$ is decisive.
\label{minimal}
